def rechteck_zeichnen(breite, hoehe):
    for i in range(hoehe):
        print("#" * breite)

rechteck_zeichnen(5, 2)
# rechteck_zeichnen(5)  # TypeError: missing 1 required positional argument: 'hoehe'

def note_berechnen(prozent):
    if prozent >= 90:
        return 1
    if prozent >= 80:
        return 2
    if prozent >= 65:
        return 3
    if prozent >= 50:
        return 4
    return 5

def ist_gerade(zahl):
    return zahl % 2 == 0

print(note_berechnen(83))  # 2
if ist_gerade(10):
    print("10 ist gerade")

def durchschnitt(werte):
    return sum(werte) / len(werte)

noten = [1, 2, 2, 3]
print(f"Schnitt: {durchschnitt(noten)}")  # Schnitt: 2.0

