    return a * 2 + b * 2

print(rechne(2, 3))

def pruefe(zahl):
    if zahl > 0:
        return "positiv"
    print("fertig")
    return "nicht positiv"

print(pruefe(5))

def maximum(a, b):
    if a > b:
        return a
    return b

print(maximum(4))
